/**
 * THE EXCHANGE'S WIRE FORMAT (bands.finance Play, 24 Sep). One contract for the browser (src/game/net.ts) and the
 * room server (game-server/, a Cloudflare Durable Object). JSON over one WebSocket per visitor.
 *
 * Safety by construction: no free text ever crosses the wire. A visitor's name is generated by the server, what
 * they say is one of PHRASES, what they do is one of EMOTES, and a leaderboard score is the server's own: a round
 * is played on the server. The player lays a band ("lay"), the server deals a seed it never sends, runs simulate()
 * (src/game/lpGame.ts) and streams the result one tick at a time as its clock reaches each tick ("tick"); the
 * player may "close" at any time, which settles the round at the last tick already sent. The browser never sees
 * the seed or any tick before its time, so there is nothing to search offline.
 *
 * THE GAME (24 Sep, the simple town): walk the town, pick up the coins lying about it, bring them to Mr Bands' desk
 * and cash them in; the stack (whole dollars of play money; a band is $1,000) grows by what they were worth. A coin's
 * worth is the server's alone: the ground shows a coin (and whether it is a mint mark), a pick shows what that one
 * was worth, and the pockets show a count until the desk reveals the cash. The four stalls are teaching games with
 * nothing on them: a round records its result against holding on the Best rounds board and touches no stack. Every
 * change to a stack is the server's own: a cash-in, or a purchase at one of the town's shops.
 *
 * THE TOWN: the walkable ground is the plaza, the boulevard ring, the four streets out to their domed ends, the ring
 * road that joins them and the four quarters between them (the Park, the Canal, the Market Square, the Station), one
 * shape for both sides (web/src/game/town.ts: walkable, nearestWalkable, PLACES, COIN_ZONES). Every named front is a
 * Place with a door; standing within DOOR_REACH_M of it a visitor may "enter" (the server checks the position,
 * records the discovery and answers what the interior shows), "buy" kit at a shop, "climb" the tower. Kit worn is in
 * PlayerState.kit for everyone to see. Once an hour the Mint spills coins along one street ("spill").
 */

/** the plaza is a disc of this radius, in world units (metres); the server clamps every position into it */
export const WORLD_RADIUS = 42;
/** a client sends at most this many moves a second; the server drops the excess */
export const MOVE_HZ = 12;
/** the server broadcasts positions this many times a second, batched */
export const TICK_HZ = 10;
/** the most visitors one room holds; the next one gets { t: "full" } */
export const ROOM_CAP = 60;
/** the fastest a walker may move, metres a second (sprint included), for the server's sanity check */
export const MAX_SPEED = 9;
/** an online round's pace: tick i (1..TICKS) goes out ROUND_TICK_MS * i after the band is laid */
export const ROUND_TICK_MS = 420;

export const EMOTES = ["wave", "tip-hat", "cheer", "shrug"] as const;
export type EmoteId = (typeof EMOTES)[number];

export const PHRASES = ["Hello", "Nice band", "Where are the fees?", "In range", "Out of range", "See you on the board", "Good game"] as const;
export type PhraseId = (typeof PHRASES)[number];

/** the hat-strap colours a visitor can pick (index 0 is Mr Bands' orange) */
export const STRAPS = ["#ff7a1a", "#1f7a4d", "#2f5d9e", "#b8321f", "#8a6a1c", "#6b3fa0"] as const;

export interface PlayerState {
  id: string;
  name: string;
  strap: number;
  x: number;
  z: number;
  /** heading, radians */
  ry: number;
  moving: boolean;
  /** their stack, dollars */
  stack: number;
  /** what they wear (bought at the town's shops) */
  kit: Kit;
}

// ---------------------------------------------------------------- the town

/** how near a door you must stand to enter, buy, climb or be counted there, metres (the server's check) */
export const DOOR_REACH_M = 3;
/**
 * the plaza's own two spots beside the PLACES of town.ts, the map's landmarks: the Guard House's front step (World.ts
 * builds it at (24, 2) turned -PI/2.4, its front 4.4 m out) and Mr Bands' desk (DESK_SPOT, a wider reach)
 */
export const GUARD_SPOT = { x: 19.8, z: 3.1 } as const;
/** where coins are cashed in: the front of Mr Bands' desk, and how near it you must stand */
export const DESK_SPOT = { x: -20.9, z: 2.8, r: 4.5 } as const;
/** the place ids the server and the shops rely on; PLACES in town.ts must use these ids for these fronts */
export const PLACE_IDS = {
  hatter: "hatter",
  cigars: "cigars",
  merchantsBank: "merchants-bank",
  coffeeEast: "coffee-east",
  clockTower: "clock-tower",
  bandsCo: "bands-co",
  booksellerCrescent: "bookseller-crescent",
  eastEnd: "east-end",
  northEnd: "north-end",
  westEnd: "west-end",
  southEnd: "south-end",
  /** the four quarters' gates on the ring road (a discovery each, nothing to enter) */
  park: "park",
  canal: "canal",
  market: "market",
  station: "station",
  /** the ring road's fronts (a line each, nothing to buy) */
  grandHotel: "grand-hotel",
  ironmonger: "ironmonger",
  chandler: "chandler",
  baker: "baker",
  apothecary: "apothecary",
  gazette: "gazette",
  /** the plaza's own (not in PLACES): the Guard House and the desk */
  guardHouse: "guard-house",
  desk: "desk",
} as const;
/** the Coffee House keeps the last this many phrases said in the plaza */
export const TALK_ROWS = 8;

// ---------------------------------------------------------------- kit and the shops

export const HATS = ["top", "bowler", "boater", "cap", "crown"] as const;
export type HatId = (typeof HATS)[number];
export const COATS = ["Ink", "Cloth", "FigInk"] as const;
export type CoatId = (typeof COATS)[number];
/** what a figure wears; the strap colour is PlayerState.strap as before */
export interface Kit {
  hat: HatId;
  coat: CoatId;
  cane: boolean;
  glasses: boolean;
  cigar: boolean;
}
export const DEFAULT_KIT: Kit = { hat: "top", coat: "Ink", cane: false, glasses: false, cigar: false };

/** which shop sells (a shop place's id is the shop, or the shop then "-" and where: "glover-west", "stationer-crescent") */
export const SHOPS = ["hatter", "glover", "cigars", "stationer", "tailor"] as const;
export type ShopId = (typeof SHOPS)[number];
/** the shop a place id names, or null when the place is not a shop */
export function shopOf(placeId: string): ShopId | null {
  const head = placeId.split("-")[0];
  return (SHOPS as readonly string[]).includes(head) ? (head as ShopId) : null;
}

export const ITEMS = ["boater", "cap", "crown", "cane", "cigar", "glasses", "coat-cloth", "coat-ink", "coat-figink"] as const;
export type ItemId = (typeof ITEMS)[number];
/** what the shops sell, dollars of play money each; one of each: what you wear is what you own, and a second is refused */
export const STOCK: readonly { item: ItemId; shop: ShopId; label: string; price: number }[] = [
  { item: "boater", shop: "hatter", label: "a boater", price: 400 },
  { item: "cap", shop: "hatter", label: "a cap", price: 250 },
  { item: "crown", shop: "hatter", label: "a crown", price: 5000 },
  { item: "cane", shop: "glover", label: "a cane", price: 600 },
  { item: "cigar", shop: "cigars", label: "a cigar", price: 150 },
  { item: "glasses", shop: "stationer", label: "reading spectacles", price: 300 },
  { item: "coat-cloth", shop: "tailor", label: "a coat in cloth", price: 200 },
  { item: "coat-ink", shop: "tailor", label: "a coat in ink", price: 200 },
  { item: "coat-figink", shop: "tailor", label: "a coat in fig ink", price: 200 },
];
/** the kit an item puts on: a hat or a coat replaces the one worn, the rest is a switch */
export function wear(kit: Kit, item: ItemId): Kit {
  switch (item) {
    case "boater":
    case "cap":
    case "crown":
      return { ...kit, hat: item };
    case "cane":
    case "cigar":
    case "glasses":
      return { ...kit, [item]: true };
    case "coat-cloth":
      return { ...kit, coat: "Cloth" };
    case "coat-ink":
      return { ...kit, coat: "Ink" };
    case "coat-figink":
      return { ...kit, coat: "FigInk" };
  }
}
/** is the item already on (so the shop refuses a second) */
export const owns = (kit: Kit, item: ItemId): boolean => JSON.stringify(wear(kit, item)) === JSON.stringify(kit);

// ---------------------------------------------------------------- the stack and the coins

/** a band: a strapped stack of $1,000 */
export const BAND = 1000;
/** a new account's stack */
export const START_STACK = 1000;
/** coins a player can pick up in a day (UTC); the rest stay on the ground for others */
export const COINS_PER_DAY = 150;
/** how near a coin you must be to pick it up, metres (the server's check) */
export const NOTE_REACH = 2;

/** a player's own account, as they see it */
export interface Me {
  stack: number;
  /** coins in the pockets: a count. What they are worth is the desk's to say, at the cash-in */
  coins: number;
  /** the UTC day coinsToday is for, "2026-09-24" */
  day: string;
  /** coins picked up today (COINS_PER_DAY) */
  coinsToday: number;
  kit: Kit;
  /** the place ids reached so far (the four ends included) */
  found: string[];
}

/** a phrase said in the plaza, as the Coffee House repeats it */
export interface TalkRow {
  name: string;
  phrase: PhraseId;
  /** minutes ago */
  ago: number;
}

/** a coin on the ground. Its worth is not here: only "picked" says what a coin was worth. A mark is drawn larger */
export interface Note {
  id: string;
  x: number;
  z: number;
  kind: "coin" | "mark";
}

export interface StackRow {
  name: string;
  stack: number;
}

export interface ScoreRow {
  name: string;
  /** the pool the round was played on ("CARDS / USDC") */
  pool: string;
  /** the round's result against holding, percent of the deposit, two decimals */
  pct: number;
  at: number;
}

// ---------------------------------------------------------------- client -> server

export type C2S =
  /** key: the account key this browser was given, to open the same account again */
  | { t: "hello"; strap: number; key?: string }
  | { t: "move"; x: number; z: number; ry: number; moving: boolean }
  | { t: "emote"; e: EmoteId }
  | { t: "say"; p: PhraseId }
  /**
   * lay a band on one of the live pools (by address, or label; the server looks it up in its own copy of the board)
   * and start a round. One round open per player at a time, one lay a second. Practice only: anything sent as a
   * stake is refused "practice only"
   */
  | { t: "lay"; pool: string; widthBins: number; offsetBins: number }
  /** pick up a coin (the server checks you stand within NOTE_REACH of it) */
  | { t: "pick"; note: string }
  /** settle the round now, at the last tick the server has sent (tick 1 if none has gone out yet) */
  | { t: "close"; roundId: string }
  /**
   * I stand at this door (a PLACES id, or "desk"): the server checks the position (DOOR_REACH_M), records the
   * discovery and answers "place"
   */
  | { t: "enter"; place: string }
  /** climb the Clock Tower (at its door): answers "place" for the tower with the hour it shows */
  | { t: "climb" }
  /** buy one of STOCK at its shop's door */
  | { t: "buy"; item: ItemId }
  /** at the desk (DESK_SPOT): the coins carried go into the stack at what they were worth; answers "cashed" then "me" */
  | { t: "cashin" };

// ---------------------------------------------------------------- server -> client

export type S2C =
  /** key: sent once, when the account is new; the browser keeps it to come back to the same stack */
  | { t: "welcome"; you: string; name: string; players: PlayerState[]; board: ScoreRow[]; me: Me; notes: Note[]; stacks: StackRow[]; key?: string; spill?: { street: number; until: number } }
  /** this player's account changed */
  | { t: "me"; me: Me }
  /** someone's stack changed (for their name tag) */
  | { t: "stack"; id: string; stack: number }
  /** coins dropped on the ground and coins gone from it */
  | { t: "notes"; add: Note[]; gone: string[] }
  /** someone picked up a coin worth v (the bubble over their head) */
  | { t: "picked"; id: string; note: string; v: number }
  /** the Mint spilled along a street (0..3, the order of town.ts's STREET_NAMES) until this time (ms since the epoch) */
  | { t: "spill"; street: number; until: number }
  /** the coins were cashed in at the desk: how many, and the dollars they went into the stack as (0 and 0: none carried) */
  | { t: "cashed"; coins: number; cash: number }
  /** the biggest stacks changed */
  | { t: "stacks"; rows: StackRow[] }
  /** this account was opened in another tab; this socket is closed */
  | { t: "elsewhere" }
  | { t: "join"; p: PlayerState }
  | { t: "leave"; id: string }
  /** batched positions: [id, x, z, ry, moving 0|1] */
  | { t: "moves"; m: [string, number, number, number, 0 | 1][] }
  | { t: "emote"; id: string; e: EmoteId }
  | { t: "say"; id: string; p: PhraseId }
  /**
   * the band is down: the pool it was laid on (public board data), its price bounds relative to p0 = 1, the pace,
   * and whether the hours are a real stretch of the pool's history (which one is kept back until the round is scored)
   */
  | { t: "laid"; roundId: string; pool: import("./lpGame").PoolParams; lower: number; upper: number; tickMs: number; real?: boolean }
  /** tick i (1..TICKS) of the server's round, sent when the server's clock reaches it; the SimResult arrays at i */
  | { t: "tick"; roundId: string; i: number; p: number; feesPct: number; valuePct: number; holdPct: number; inRange: boolean }
  /**
   * the round is settled (closed, or it reached TICKS): pct against holding at the hour it settled (`at`); rank on
   * the Best rounds board, or null when it was not this name's best; for a real round, when its stretch of history
   * began (unix seconds)
   */
  | { t: "scored"; roundId: string; pct: number; at: number; rank: number | null; from?: number }
  | { t: "board"; rows: ScoreRow[] }
  | { t: "full" }
  /** the visitor is sending too much; messages are being dropped */
  | { t: "slow" }
  /**
   * what the interior shows: the Coffee House's talk, the tower's hour (UTC, 0..23), a shop's stock with what is
   * already worn; the rest carry the id alone
   */
  | { t: "place"; id: string; talk?: TalkRow[]; hour?: number; stock?: { item: ItemId; price: number; owned: boolean }[] }
  /** the first time this player reached the door */
  | { t: "found"; place: string }
  /** the purchase went through (the new kit follows in "me" and "kit") */
  | { t: "bought"; item: ItemId }
  /** someone's kit changed (the buyer included) */
  | { t: "kit"; id: string; kit: Kit }
  /**
   * fixed server strings: "not there" (not at that door, or not at the desk), "no stack" (cannot afford), "have one",
   * "notes done" (today's coins are all picked up), "practice only" (a stake was sent), and the round's own:
   * "unknown pool", "board unavailable", "round in play", "no such round", "bad choice"
   */
  | { t: "error"; why: string };

export const isEmote = (v: unknown): v is EmoteId => typeof v === "string" && (EMOTES as readonly string[]).includes(v);
export const isPhrase = (v: unknown): v is PhraseId => typeof v === "string" && (PHRASES as readonly string[]).includes(v);
export const isItem = (v: unknown): v is ItemId => typeof v === "string" && (ITEMS as readonly string[]).includes(v);
export const isHat = (v: unknown): v is HatId => typeof v === "string" && (HATS as readonly string[]).includes(v);
export const isCoat = (v: unknown): v is CoatId => typeof v === "string" && (COATS as readonly string[]).includes(v);
/** a stored or received kit put right: anything missing or malformed falls back to DEFAULT_KIT's */
export function cleanKit(k: unknown): Kit {
  const o = typeof k === "object" && k !== null ? (k as Record<string, unknown>) : {};
  return {
    hat: isHat(o.hat) ? o.hat : DEFAULT_KIT.hat,
    coat: isCoat(o.coat) ? o.coat : DEFAULT_KIT.coat,
    cane: o.cane === true,
    glasses: o.glasses === true,
    cigar: o.cigar === true,
  };
}
